cd /app/seeds && python3 - <<'E'
import glob
for f in glob.glob('*.csv'):
    b=open(f,'rb').read()
    try: b.decode('utf-8'); print(f,'utf8 ok', b[:3]==b'\xef\xbb\xbf', b'\r\n' in b)
    except Exception as e: print(f,'not utf8',e, b'\r\n' in b)
    try: b.decode('cp1252')
    except Exception as e: print(' cp1252 fail',e)
E
cut -d, -f8 specimens.csv|sort|uniq -c; cut -d, -f3 taxa.csv|sort|uniq -c; grep -c . *.csv
python3 - <<'E'
import csv
r=list(csv.DictReader(open('taxa.csv',encoding='utf-8')))
seen=set()
for x in r:
    if x['parent_id'] and int(x['parent_id']) not in seen: print('fwd',x)
    seen.add(int(x['taxon_id']))
E
